import ctypes
import os

def assert_test():
    # Load the libraries in the correct order
    try:
        libgslcblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        raise RuntimeError(f"Failed to load libraries: {e}")

    # Access the 'gsl_integration_fixed_chebyshev2' symbol
    try:
        gsl_integration_fixed_chebyshev2 = ctypes.cast(
            ctypes.addressof(gsl.gsl_integration_fixed_chebyshev2),
            ctypes.POINTER(ctypes.c_void_p)
        )
    except AttributeError:
        raise RuntimeError("Failed to access 'gsl_integration_fixed_chebyshev2' symbol")

    # Verify the symbol is loaded correctly
    assert gsl_integration_fixed_chebyshev2 is not None, "Symbol 'gsl_integration_fixed_chebyshev2' is None"

    print("Successfully loaded and accessed 'gsl_integration_fixed_chebyshev2' symbol.")

if __name__ == "__main__":
    assert_test()
